update public.lessons set content = jsonb_set(content, '{blocks,7,content}', to_jsonb('{"v":1,"kind":"formula","title":"Entropie approximative","items":[{"label":"Alphabet de 62 caractères","formula":"bits = longueur × log2(taille de l’alphabet)","example":"62 caractères possibles : a-z A-Z 0-9\n8 caractères : 8 × log2(62) ≈ 47,6 bits\n12 caractères : 12 × log2(62) ≈ 71,5 bits","tone":"cyan"},{"label":"Diceware, 7776 mots","formula":"bits = mots × log2(7776)","example":"5 mots ≈ 64,6 bits\n6 mots ≈ 77,5 bits","tone":"green"}]}'::text))
