update public.lessons set content = jsonb_set(content, '{blocks,5,content}', to_jsonb('{"v":1,"kind":"cards","title":"Questions simples à poser à chaque ligne","columns":2,"items":[{"term":"Quand ?","text":"horodatage, fuseau, ordre relatif","tone":"blue"},{"term":"Où ?","text":"machine, application, équipement","tone":"green"},{"term":"Qui ?","text":"compte, service, adresse source","tone":"violet"},{"term":"Quoi ?","text":"action observée","tone":"cyan"},{"term":"Résultat ?","text":"succès, échec, refus, erreur, code","tone":"amber"},{"term":"Preuve ?","text":"champ exact qui permet de le dire","tone":"red"}]}'::text))
