update public.lessons set content = jsonb_set(content, '{blocks,9,content}', to_jsonb('{"v":1,"kind":"compare","title":"Une annotation prudente","sides":[{"title":"Ce que disent les lignes","tone":"blue","mark":"dot","items":["Ligne SSH : échec de connexion, compte connu, source externe","Ligne web : tentative de connexion refusée, navigateur déclaré","Ligne pare-feu : accès SSH bloqué, règle réseau appliquée"]},{"title":"Ce qu’il manque","tone":"amber","mark":"dot","items":["fréquence et historique","propriétaire de l’adresse","rôle habituel du compte","autres sources"]}],"verdict":"Une ligne décrit un fait ; le contexte décide du sens."}'::text))
