update public.lessons set content = jsonb_set(content, '{blocks,5,content}', to_jsonb('{"v":1,"kind":"flow","title":"Du noyau Linux à la distribution","nodes":[{"label":"Noyau Linux","text":"gère le matériel, la mémoire et les processus","icon":"server","tone":"green"},{"label":"Outils et paquets","text":"configuration et documentation","icon":"package","tone":"blue"},{"label":"Distribution","text":"système complet prêt à l’usage","icon":"laptop","tone":"violet"}],"caption":"Familles courantes : Debian et Ubuntu pour l’apprentissage et des serveurs courants ; RHEL et Fedora en entreprise, avec `dnf` et SELinux ; Arch reste très manuel et très formateur."}'::text))
