update public.lessons set content = jsonb_set(content, '{blocks,5,content}', to_jsonb('{"v":1,"kind":"anatomy","title":"Nom affiché ≠ adresse réelle","lines":[[{"text":"Affiché :","tone":"neutral"},{"text":"Comptabilité Atlas","label":"nom vu à l’écran","tone":"green"}],[{"text":"From :","tone":"neutral"},{"text":"facturation@atlas-service.example.org","label":"adresse réelle","tone":"amber"}],[{"text":"Reply-To :","tone":"neutral"},{"text":"recouvrement@example.net","label":"où partira la réponse","tone":"red"}]],"caption":"Signal : la réponse part vers `example.net`, pas vers le domaine affiché à l’écran."}'::text))
where id = 'f9873b02-e1f6-24c4-5bce-7081d13404d5' and content #>> '{blocks,5,type}' = 'schema' and md5(content #>> '{blocks,5,content}') = 'bdf3e6ec819db2d26e05e43918db36aa';
update public.lessons set content = jsonb_set(content, '{blocks,7,content}', to_jsonb('{"v":1,"kind":"anatomy","title":"Extrait d’en-têtes annoté","lines":[[{"text":"Authentication-Results: mx.example.org;","label":"résumé des contrôles","tone":"neutral"}],[{"text":"spf=fail","label":"échec SPF","tone":"red"},{"text":"smtp.mailfrom=atlas-service.example.org","label":"MAIL FROM","tone":"amber"}],[{"text":"dkim=none","label":"signature absente","tone":"amber"},{"text":"header.d=none","label":"pas de domaine DKIM","tone":"amber"}],[{"text":"dmarc=fail","label":"échec DMARC","tone":"red"},{"text":"Reply-To: aide@example.net","label":"la réponse part ailleurs","tone":"red"}]],"caption":"Lecture simple : `fail` = échec, `none` = absent, et la réponse veut partir ailleurs."}'::text))
